<style>
.sr-layout{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:20px;align-items:start}.sr-main{display:grid;gap:20px}.sr-aside{display:grid;gap:20px;position:sticky;top:92px}.sr-opportunity-summary{display:flex;flex-direction:column;justify-content:center;padding:10px 14px;border:1px solid var(--border);border-radius:12px;background:var(--surface-soft)}.sr-opportunity-summary span,.sr-opportunity-summary small{color:var(--muted)}.sr-form-panel{margin:18px;border-top:1px solid var(--border);padding-top:14px}.sr-form-panel summary{cursor:pointer;font-weight:700}.sr-form-panel form{margin-top:16px}.sr-card-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px;padding:18px}.sr-card{border:1px solid var(--border);border-radius:14px;padding:16px;background:var(--surface-soft)}.sr-card>div{display:flex;justify-content:space-between;gap:10px}.sr-card h3{margin:12px 0 8px}.sr-card p{color:var(--muted)}.sr-review-form{display:grid;gap:12px;padding:18px;border-top:1px solid var(--border)}.sr-breakdown{display:grid;gap:0}.sr-breakdown div{display:flex;justify-content:space-between;gap:15px;padding:12px 0;border-bottom:1px solid var(--border)}.sr-breakdown dd{margin:0;text-align:right}.sr-control-list{display:grid;gap:10px;margin:0;padding-left:20px;color:var(--muted)}.data-table tr.is-selected{background:var(--surface-soft)}.timeline-list{padding:0 18px 18px}.timeline-list article{display:grid;grid-template-columns:auto 1fr;gap:12px;padding:14px 0;border-bottom:1px solid var(--border)}.timeline-list p{margin:4px 0;color:var(--muted)}@media(max-width:1080px){.sr-layout{grid-template-columns:1fr}.sr-aside{position:static;grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:720px){.sr-aside{grid-template-columns:1fr}.sr-opportunity-summary{grid-column:1/-1}}
</style>
